CREATE TABLE IF NOT EXISTS ssinfo_roles (id VARCHAR(64) PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS ssinfo_permissions (id VARCHAR(64) PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS ssinfo_role_permissions (role_id VARCHAR(64) NOT NULL, permission_id VARCHAR(64) NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES ssinfo_roles(id), FOREIGN KEY(permission_id) REFERENCES ssinfo_permissions(id));
CREATE TABLE IF NOT EXISTS ssinfo_users (id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at DATETIME NULL, INDEX(status));
CREATE TABLE IF NOT EXISTS ssinfo_user_roles (user_id CHAR(36) NOT NULL, role_id VARCHAR(64) NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES ssinfo_users(id), FOREIGN KEY(role_id) REFERENCES ssinfo_roles(id));
CREATE TABLE IF NOT EXISTS ssinfo_sessions (token_hash CHAR(64) PRIMARY KEY, user_id CHAR(36) NOT NULL, expires_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES ssinfo_users(id) ON DELETE CASCADE, INDEX(expires_at));
CREATE TABLE IF NOT EXISTS ssinfo_password_resets (token_hash CHAR(64) PRIMARY KEY, user_id CHAR(36) NOT NULL, expires_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES ssinfo_users(id) ON DELETE CASCADE, INDEX(expires_at));
CREATE TABLE IF NOT EXISTS ssinfo_rate_limits (id CHAR(64) PRIMARY KEY, hits INT NOT NULL, expires_at DATETIME NOT NULL, INDEX(expires_at));
CREATE TABLE IF NOT EXISTS ssinfo_audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id CHAR(36) NULL, action VARCHAR(100) NOT NULL, target VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(created_at));
CREATE TABLE IF NOT EXISTS ssinfo_tool_categories (id VARCHAR(64) PRIMARY KEY, slug VARCHAR(190) NOT NULL UNIQUE, name VARCHAR(190) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', data JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ssinfo_tools (id VARCHAR(100) PRIMARY KEY, slug VARCHAR(190) NOT NULL UNIQUE, name VARCHAR(190) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', data JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ssinfo_tool_category_mapping (tool_id VARCHAR(100) NOT NULL, category_id VARCHAR(64) NOT NULL, PRIMARY KEY(tool_id,category_id), FOREIGN KEY(tool_id) REFERENCES ssinfo_tools(id), FOREIGN KEY(category_id) REFERENCES ssinfo_tool_categories(id));
CREATE TABLE IF NOT EXISTS ssinfo_blog_categories (id VARCHAR(64) PRIMARY KEY, slug VARCHAR(190) NOT NULL UNIQUE, name VARCHAR(190) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', data JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ssinfo_blog_tags (id VARCHAR(64) PRIMARY KEY, slug VARCHAR(190) NOT NULL UNIQUE, name VARCHAR(190) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', data JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ssinfo_blog_posts (id VARCHAR(100) PRIMARY KEY, slug VARCHAR(190) NOT NULL UNIQUE, name VARCHAR(190) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'draft', data JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ssinfo_blog_post_tags (post_id VARCHAR(100) NOT NULL, tag_id VARCHAR(64) NOT NULL, PRIMARY KEY(post_id,tag_id), FOREIGN KEY(post_id) REFERENCES ssinfo_blog_posts(id), FOREIGN KEY(tag_id) REFERENCES ssinfo_blog_tags(id));
CREATE TABLE IF NOT EXISTS ssinfo_seo_pages (id VARCHAR(100) PRIMARY KEY, slug VARCHAR(190) NOT NULL UNIQUE, name VARCHAR(190) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', data JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ssinfo_seo_redirects (id VARCHAR(100) PRIMARY KEY, source VARCHAR(255) NOT NULL UNIQUE, destination VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ssinfo_site_settings (id VARCHAR(64) PRIMARY KEY, data JSON NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ssinfo_admin_settings (user_id CHAR(36) PRIMARY KEY, data JSON NOT NULL, FOREIGN KEY(user_id) REFERENCES ssinfo_users(id));
CREATE TABLE IF NOT EXISTS ssinfo_analytics_visits (id CHAR(36) PRIMARY KEY, visitor_hash CHAR(64) NOT NULL, device VARCHAR(16) NOT NULL, country CHAR(2) NULL, source VARCHAR(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(created_at), INDEX(visitor_hash));
CREATE TABLE IF NOT EXISTS ssinfo_analytics_events (id CHAR(36) PRIMARY KEY, visit_id CHAR(36) NOT NULL, kind VARCHAR(20) NOT NULL, path VARCHAR(255) NOT NULL, tool VARCHAR(100) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(visit_id) REFERENCES ssinfo_analytics_visits(id) ON DELETE CASCADE, INDEX(created_at,kind), INDEX(tool,created_at));
CREATE TABLE IF NOT EXISTS ssinfo_analytics_tool_usage (day DATE NOT NULL, tool VARCHAR(100) NOT NULL, uses BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(day,tool));
CREATE TABLE IF NOT EXISTS ssinfo_analytics_daily (day DATE PRIMARY KEY, page_views BIGINT NOT NULL DEFAULT 0, tool_uses BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS ssinfo_analytics_country (day DATE NOT NULL, country VARCHAR(16) NOT NULL, visits BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(day,country));
CREATE TABLE IF NOT EXISTS ssinfo_analytics_device (day DATE NOT NULL, device VARCHAR(16) NOT NULL, visits BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(day,device));
CREATE TABLE IF NOT EXISTS ssinfo_search_console_properties (id CHAR(36) PRIMARY KEY, property_url VARCHAR(255) NOT NULL UNIQUE, encrypted_tokens TEXT NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ssinfo_search_console_data (id BIGINT AUTO_INCREMENT PRIMARY KEY, property_id CHAR(36) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, dimension VARCHAR(20) NOT NULL, data JSON NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE(property_id,start_date,end_date,dimension), FOREIGN KEY(property_id) REFERENCES ssinfo_search_console_properties(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS ssinfo_oauth_states (id CHAR(64) PRIMARY KEY, user_id CHAR(36) NOT NULL, expires_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS ssinfo_ad_slots (id VARCHAR(100) PRIMARY KEY, slug VARCHAR(190) NOT NULL UNIQUE, name VARCHAR(190) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'inactive', data JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ssinfo_ad_campaigns (id VARCHAR(100) PRIMARY KEY, slug VARCHAR(190) NOT NULL UNIQUE, name VARCHAR(190) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'inactive', data JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ssinfo_ad_settings (id VARCHAR(64) PRIMARY KEY, data JSON NOT NULL);
CREATE TABLE IF NOT EXISTS ssinfo_plans (id VARCHAR(100) PRIMARY KEY, slug VARCHAR(190) NOT NULL UNIQUE, name VARCHAR(190) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'inactive', data JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ssinfo_subscriptions (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, plan_id VARCHAR(100) NOT NULL, status VARCHAR(20) NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES ssinfo_users(id), FOREIGN KEY(plan_id) REFERENCES ssinfo_plans(id), INDEX(status,ends_at));
CREATE TABLE IF NOT EXISTS ssinfo_payments (id CHAR(36) PRIMARY KEY, subscription_id CHAR(36) NOT NULL, provider VARCHAR(50) NOT NULL, provider_reference VARCHAR(190) NOT NULL UNIQUE, amount DECIMAL(12,2) NOT NULL, currency CHAR(3) NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(subscription_id) REFERENCES ssinfo_subscriptions(id));
CREATE TABLE IF NOT EXISTS ssinfo_api_keys (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, name VARCHAR(120) NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, scopes JSON NOT NULL, rate_limit INT NOT NULL DEFAULT 60, revoked_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES ssinfo_users(id));
CREATE TABLE IF NOT EXISTS ssinfo_api_usage (id BIGINT AUTO_INCREMENT PRIMARY KEY, api_key_id CHAR(36) NOT NULL, endpoint VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(api_key_id) REFERENCES ssinfo_api_keys(id), INDEX(created_at));
